func:
// Recebe o JSON publicado pelo app17-9 em FIAPIoT/motor/features.
// Como o no MQTT-in esta em datatype "json", msg.payload ja chega como objeto;
// mesmo assim protegemos contra string.
let p = msg.payload;
if (typeof p === "string") {
    try { p = JSON.parse(p); }
    catch (e) { node.error("Payload nao e JSON valido", msg); return null; }
}

// label vem do BOTAO do ESP32 (app17-9): ligado_normal / ligado_anomalia.
const label = p.label || "desconhecido";

// Campos numericos: as 7 features usadas no ML (mean_*, std_*, rms_mag),
// as 3 rms_* herdadas do app17-8 e o ts_epoch_ms (NTP) so para referencia.
const fields = {
    mean_ax: Number(p.mean_ax),
    mean_ay: Number(p.mean_ay),
    mean_az: Number(p.mean_az),
    std_ax:  Number(p.std_ax),
    std_ay:  Number(p.std_ay),
    std_az:  Number(p.std_az),
    rms_ax:  Number(p.rms_ax),
    rms_ay:  Number(p.rms_ay),
    rms_az:  Number(p.rms_az),
    rms_mag: Number(p.rms_mag),
    ts_epoch_ms: Number(p.ts_epoch_ms) || 0
};

// label como TAG: facilita o group by no Flux e no notebook (treino).
const tags = {
    label:  label,
    device: p.device || "esp32"
};

node.status({ fill: "green", shape: "dot",
    text: label + " | rms_mag=" + (isFinite(fields.rms_mag) ? fields.rms_mag.toFixed(2) : "?") });

// node-red-contrib-influxdb: payload = [fields, tags]
msg.payload = [fields, tags];
return msg;
